import { stringify } from 'yaml';

/** One observation from the repo, always with a `file:line` citation. */
export interface Fact {
  key: string;
  value: string | number | boolean | Record<string, unknown>;
  source: string;
}

export type Provenance =
  | { kind: 'SOURCE'; ref: string }
  | { kind: 'HOST'; ref: string }
  | { kind: 'INFERRED'; reason: string };

export interface Command {
  /** argv, never a shell string. `{class}` / `{file}` are the only substitution slots. */
  argv: string[];
  provenance: Provenance;
}

export interface ServiceNeed {
  name: string;
  kind: string;
  image?: string;
  provenance: Provenance;
}

export type Stack = 'java-maven' | 'node' | 'unknown';

export interface EnvSpec {
  specVersion: 1;
  repo: string;
  derivedFrom: { ref: string; sha: string };
  target: 'host' | 'cell';
  stack: Stack;
  toolchain: Record<string, { requirement?: string; measured?: string; provenance: Provenance }>;
  services: ServiceNeed[];
  /** setup (dependency install) → build (L1) → testAll (L2 baseline) → testOne (repro slot). */
  commands: { setup?: Command; build?: Command; testAll?: Command; testOne?: Command; coverage?: Command };
  needs: { containerRuntime: boolean };
  warnings: string[];
}

export function renderSpec(spec: EnvSpec): string {
  return `# Generated by Gatehouse. Every value cites where it came from (SOURCE file:line, HOST measurement, or INFERRED reason).\n${stringify(spec, { lineWidth: 0 })}`;
}

export function provenanceLabel(p: Provenance): string {
  return p.kind === 'INFERRED' ? `INFERRED: ${p.reason}` : `${p.kind} ${p.ref}`;
}
